local IngotCasterMaker = {}
local PRODUCTS = {
    iron_ingotcaster = { name = "Železni palicni ulitev", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni palicni ulitev za livarje." },
    bronze_ingotcaster = { name = "Bronast palicni ulitev", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast palicni ulitev za livarje." },
    silver_ingotcaster = { name = "Srebrn palicni ulitev", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn palicni ulitev za livarje." },
    gilded_ingotcaster = { name = "Pozlačen palicni ulitev", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen palicni ulitev za livarje." },
    jewel_set_ingotcaster = { name = "Draguljast palicni ulitev", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast palicni ulitev za livarje." },
    royal_sovereign_ingotcaster = { name = "Kraljevski suveren palicni ulitev", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren palicni ulitev z biseri za krono." },
}
local BUILDINGS = {
    ingotcaster_workshop = { name = "Ingotcaster delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    ingotcaster_house = { name = "Ingotcaster hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_ingotcaster_atelier = { name = "Mojstrski ingotcaster atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_ingotcaster_palace = { name = "Suverena ingotcaster palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
IngotCasterMaker.ironStock = 16; IngotCasterMaker.bronzeStock = 14; IngotCasterMaker.woodStock = 10; IngotCasterMaker.leatherStock = 8; IngotCasterMaker.silverStock = 8; IngotCasterMaker.goldStock = 6; IngotCasterMaker.jewelStock = 4; IngotCasterMaker.pearlStock = 4
IngotCasterMaker.productStock = {}; IngotCasterMaker.buildings = {}; IngotCasterMaker.maker = nil; IngotCasterMaker.activeMaking = {}; IngotCasterMaker.totalProducts = 0; IngotCasterMaker.dayTimer = 0
function IngotCasterMaker.init() IngotCasterMaker.ironStock=16; IngotCasterMaker.bronzeStock=14; IngotCasterMaker.woodStock=10; IngotCasterMaker.leatherStock=8; IngotCasterMaker.silverStock=8; IngotCasterMaker.goldStock=6; IngotCasterMaker.jewelStock=4; IngotCasterMaker.pearlStock=4; IngotCasterMaker.productStock={}; IngotCasterMaker.buildings={}; IngotCasterMaker.maker=nil; IngotCasterMaker.activeMaking={}; IngotCasterMaker.totalProducts=0; IngotCasterMaker.dayTimer=0; print("[IngotCasterMaker] Royal Ingot Caster Maker System initialized (6 products, 4 buildings)") end
function IngotCasterMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; IngotCasterMaker.maker={name=n or ("Palicar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Palicar najet: %s (spretnost: %d)",IngotCasterMaker.maker.name,s),"success") end; return true end
function IngotCasterMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function IngotCasterMaker.build(id) local ok,e=IngotCasterMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(IngotCasterMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function IngotCasterMaker.getQualityBonus() local b=0; for _,bd in ipairs(IngotCasterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function IngotCasterMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and IngotCasterMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and IngotCasterMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and IngotCasterMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and IngotCasterMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and IngotCasterMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and IngotCasterMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and IngotCasterMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and IngotCasterMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #IngotCasterMaker.buildings==0 then return false,"Potrebna palicna delavnica" end; if not IngotCasterMaker.maker then return false,"Potreben palicar" end; return true end
function IngotCasterMaker.make(pt,qty) qty=qty or 1; local ok,e=IngotCasterMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then IngotCasterMaker.ironStock=IngotCasterMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then IngotCasterMaker.bronzeStock=IngotCasterMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then IngotCasterMaker.woodStock=IngotCasterMaker.woodStock-d.woodCost*qty end; if d.leatherCost then IngotCasterMaker.leatherStock=IngotCasterMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then IngotCasterMaker.silverStock=IngotCasterMaker.silverStock-d.silverCost*qty end; if d.goldCost then IngotCasterMaker.goldStock=IngotCasterMaker.goldStock-d.goldCost*qty end; if d.jewelCost then IngotCasterMaker.jewelStock=IngotCasterMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then IngotCasterMaker.pearlStock=IngotCasterMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if IngotCasterMaker.maker then t=math.max(1,t-math.floor(IngotCasterMaker.maker.skill/13)) end; table.insert(IngotCasterMaker.activeMaking,{id="ingotcaster_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function IngotCasterMaker.completeMaking(m) local q=1.0+(IngotCasterMaker.getQualityBonus()/100); if IngotCasterMaker.maker then q=q+(IngotCasterMaker.maker.skill/140) end; q=math.min(2.5,q); IngotCasterMaker.productStock[m.productType]=(IngotCasterMaker.productStock[m.productType] or 0)+m.quantity; IngotCasterMaker.totalProducts=IngotCasterMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if IngotCasterMaker.maker then IngotCasterMaker.maker.itemsMade=IngotCasterMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then IngotCasterMaker.maker.skill=math.min(100,IngotCasterMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Palica izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"ingotcaster.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function IngotCasterMaker.update(dt) if not _G.state then return end; IngotCasterMaker.dayTimer=IngotCasterMaker.dayTimer+dt; if IngotCasterMaker.dayTimer>=30 then IngotCasterMaker.dayTimer=0; for i=#IngotCasterMaker.activeMaking,1,-1 do local m=IngotCasterMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then IngotCasterMaker.completeMaking(m); table.remove(IngotCasterMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(IngotCasterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if IngotCasterMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function IngotCasterMaker.getStats() return {ironStock=IngotCasterMaker.ironStock,bronzeStock=IngotCasterMaker.bronzeStock,woodStock=IngotCasterMaker.woodStock,leatherStock=IngotCasterMaker.leatherStock,silverStock=IngotCasterMaker.silverStock,goldStock=IngotCasterMaker.goldStock,jewelStock=IngotCasterMaker.jewelStock,pearlStock=IngotCasterMaker.pearlStock,productStock=IngotCasterMaker.productStock,numBuildings=#IngotCasterMaker.buildings,hasMaker=IngotCasterMaker.maker~=nil,makerName=IngotCasterMaker.maker and IngotCasterMaker.maker.name or "—",makerSkill=IngotCasterMaker.maker and IngotCasterMaker.maker.skill or 0,activeMaking=#IngotCasterMaker.activeMaking,totalProducts=IngotCasterMaker.totalProducts} end
return IngotCasterMaker
